  function decorateBenefitCards(id){
    var icons = BENEFIT_ICONS[id];
    if (!icons) return;
    var sectionTitle = app.querySelector('p.kwiz-benefits__title');
    if (sectionTitle) {
      var sectionHeading = document.createElement('h2');
      sectionHeading.className = sectionTitle.className;
      sectionHeading.textContent = sectionTitle.textContent;
      sectionTitle.parentNode.replaceChild(sectionHeading, sectionTitle);
    }
    var cards = app.querySelectorAll('.kwiz-bcard');
    for (var i = 0; i < cards.length; i++) {
      var card = cards[i], text = card.querySelector('p');
      if (!text || card.querySelector('.kwiz-bcard__icon')) continue;
      var content = document.createElement('div');
      content.className = 'kwiz-bcard__content';
      var icon = document.createElement('span');
      icon.className = 'kwiz-bcard__icon';
      icon.setAttribute('aria-hidden', 'true');
      icon.innerHTML = '<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" focusable="false"><path stroke-linecap="round" stroke-linejoin="round" d="' + BENEFIT_ICON_PATHS[icons[i]] + '"></path></svg>';
      card.insertBefore(content, text);
      var header = document.createElement('div');
      header.className = 'kwiz-bcard__header';
      var copy = document.createElement('div');
      copy.className = 'kwiz-bcard__copy';
      var title = document.createElement('h3');
      title.className = 'kwiz-bcard__title';
      title.textContent = BENEFIT_TITLES[id][i];
      header.appendChild(title);
      header.appendChild(icon);
      content.appendChild(header);
      copy.appendChild(text);
      content.appendChild(copy);
      if (icons[i] === 'flight') card.classList.add('kwiz-bcard--airlines');
      if (id === 'stage2-other' && card.classList.contains('kwiz-bcard--dark')) card.classList.add('kwiz-bcard--compact');
    }
  }

  // Короткие описания — в две строки; уже многострочный текст не меняем.
  function balanceBenefitDescriptions(){
    if (!app) return;
    var sectionTitle = app.querySelector('.kwiz-benefits__title');
    var benefits = app.querySelector('.kwiz-benefits');
    if (sectionTitle && benefits) benefits.style.setProperty('--kwiz-benefit-title-size', getComputedStyle(sectionTitle).fontSize);
    var texts = app.querySelectorAll('.kwiz-bcard__copy p'), breaks = [];
    for (var i = 0; i < texts.length; i++) {
      var text = texts[i];
      if (!text._kwizOriginalText) text._kwizOriginalText = text.textContent;
      text.textContent = text._kwizOriginalText;
    }
    for (var j = 0; j < texts.length; j++) {
      var paragraph = texts[j], original = paragraph._kwizOriginalText;
      if (paragraph.closest('.kwiz-bcard--airlines.kwiz-bcard--dark')) continue;
      var range = document.createRange();
      range.selectNodeContents(paragraph);
      var rects = range.getClientRects(), lines = [];
      for (var r = 0; r < rects.length; r++) {
        var top = Math.round(rects[r].top);
        if (lines.indexOf(top) === -1) lines.push(top);
      }
      if (lines.length !== 1) continue;
      var words = original.match(/\S+/g);
      if (!words || words.length < 2) continue;
      var tail = words.length > 3 ? 2 : 1;
      var matches = /\S+/g, match, wordIndex = 0, cutAt = 0;
      while ((match = matches.exec(original))) {
        if (wordIndex++ === words.length - tail) { cutAt = match.index; break; }
      }
      breaks.push({ paragraph: paragraph, before: original.slice(0, cutAt).trim(), after: original.slice(cutAt) });
    }
    for (var b = 0; b < breaks.length; b++) {
      var item = breaks[b];
      item.paragraph.textContent = item.before;
      item.paragraph.appendChild(document.createElement('br'));
      item.paragraph.appendChild(document.createTextNode(item.after));
    }
  }

